"""AITunnel Qwen adapter for one normalized judge vote."""

from __future__ import annotations

from collections.abc import Callable, Mapping
from copy import deepcopy
import json
from math import isfinite
from typing import Literal, Protocol

from pydantic import BaseModel, ConfigDict, JsonValue, ValidationError
import requests

from src.experiment.config import LLMConfig
from src.experiment.prompts import PromptSet
from src.experiment.schemas import Collegium, JudgeResponse, PreparedBout
from src.judges.base import BaseJudge
from src.judges.errors import (
    JudgeConfigurationError,
    JudgeResponseFormatError,
    PermanentJudgeTransportError,
    TransientJudgeError,
)


class _ChoicePayload(BaseModel):
    """The only content Qwen may return."""

    model_config = ConfigDict(extra="forbid", strict=True)
    choice: Literal["player_1", "player_2"]


class _HTTPResponse(Protocol):
    status_code: int
    text: str

    def json(self) -> object: ...


PostCallable = Callable[..., _HTTPResponse]
_RESERVED_PARAMETERS = frozenset(
    {"model", "messages", "response_format", "stream", "n"}
)
_SENSITIVE_KEYS = frozenset(
    {"authorization", "credentials", "accesstoken", "apikey", "cookie", "setcookie"}
)
_NON_NEGATIVE_USAGE_FIELDS = frozenset(
    {
        "prompt_tokens",
        "completion_tokens",
        "total_tokens",
        "input_tokens",
        "output_tokens",
        "cost_rub",
    }
)


class LLMJudge(BaseJudge):
    """Stateless Qwen adapter through AITunnel chat completions."""

    SUPPORTED_MODEL_IDS = frozenset({"qwen3.7-flash", "qwen3.8-flash"})
    REQUIRED_PARAMETERS = frozenset({"max_tokens"})

    def __init__(
        self,
        config: LLMConfig,
        prompts: PromptSet,
        *,
        environ: Mapping[str, str] | None = None,
        post: PostCallable = requests.post,
    ) -> None:
        super().__init__(config, prompts, environ=environ)
        self._post = post

    def _validate_provider_configuration(self) -> None:
        conflicts = sorted(_RESERVED_PARAMETERS.intersection(self._config.parameters))
        if conflicts:
            raise JudgeConfigurationError(
                "Qwen request fields are managed by the adapter and cannot "
                "be configured: " + ", ".join(conflicts)
            )
        max_tokens = self._config.parameters.get("max_tokens")
        if not isinstance(max_tokens, int) or isinstance(max_tokens, bool) or max_tokens < 16:
            raise JudgeConfigurationError("max_tokens must be an integer >= 16")
        reasoning = self._config.parameters.get("reasoning")
        if reasoning is not None:
            if not isinstance(reasoning, dict):
                raise JudgeConfigurationError("reasoning must be an object")
            unknown = sorted(set(reasoning) - {"effort", "exclude", "context", "mode"})
            if unknown:
                raise JudgeConfigurationError(
                    "Unsupported reasoning fields: " + ", ".join(unknown)
                )
            effort = reasoning.get("effort")
            if effort is not None and effort not in {
                "none", "minimal", "low", "medium", "high", "xhigh", "max"
            }:
                raise JudgeConfigurationError("reasoning.effort is unsupported")
            exclude = reasoning.get("exclude")
            if exclude is not None and not isinstance(exclude, bool):
                raise JudgeConfigurationError("reasoning.exclude must be boolean")

    def _evaluate_once(
        self, bout: PreparedBout, collegium: Collegium
    ) -> JudgeResponse:
        secret = self._secret()
        try:
            response = self._post(
                str(self._config.api_url),
                headers={
                    "Authorization": f"Bearer {secret}",
                    "Content-Type": "application/json",
                },
                json=self._request_payload(bout, collegium),
                timeout=self._config.timeout_seconds,
                allow_redirects=False,
            )
        except requests.Timeout as error:
            raise TransientJudgeError("AITunnel Qwen request timed out") from error
        except requests.ConnectionError as error:
            raise TransientJudgeError(
                "AITunnel Qwen connection was interrupted"
            ) from error
        except requests.RequestException as error:
            raise PermanentJudgeTransportError(
                f"AITunnel Qwen transport failure ({type(error).__name__})"
            ) from error

        self._check_http_status(response.status_code)
        try:
            decoded = response.json()
        except (TypeError, ValueError) as error:
            raise JudgeResponseFormatError("AITunnel Qwen returned invalid JSON") from error
        raw_response = self._json_value(decoded, secret=secret)
        if not isinstance(raw_response, dict):
            raise JudgeResponseFormatError("AITunnel response must be a JSON object")

        try:
            choices = raw_response["choices"]
            if not isinstance(choices, list) or len(choices) != 1:
                raise ValueError("expected exactly one choice")
            choice_record = choices[0]
            if not isinstance(choice_record, dict):
                raise TypeError("choices[0] must be an object")
            finish_reason = choice_record.get("finish_reason")
            if finish_reason != "stop":
                raise ValueError(f"finish_reason must be stop, got {finish_reason!r}")
            message = choice_record["message"]
            if not isinstance(message, dict):
                raise TypeError("choices[0].message must be an object")
            content = message["content"]
            if not isinstance(content, str):
                raise TypeError("message.content must be a string")
            parsed = _ChoicePayload.model_validate_json(content)
            usage = self._usage(raw_response.get("usage"))
        except (KeyError, TypeError, ValueError, ValidationError) as error:
            raise JudgeResponseFormatError(
                f"Invalid structured AITunnel Qwen response: {error}"
            ) from error

        return JudgeResponse(
            winner=parsed.choice,
            probabilities=None,
            raw_response=raw_response,
            usage=usage,
        )

    def _request_payload(
        self, bout: PreparedBout, collegium: Collegium
    ) -> dict[str, object]:
        bout_json = json.dumps(
            bout.model_dump(mode="json"),
            ensure_ascii=False,
            separators=(",", ":"),
        )
        payload: dict[str, object] = deepcopy(self._config.parameters)
        payload.update(
            {
                "model": self.api_model_id,
                "messages": [
                    {"role": "system", "content": self.prompt_for(collegium).text},
                    {
                        "role": "user",
                        "content": (
                            "Полные данные управленческого поединка (JSON):\n"
                            + bout_json
                            + "\nВыбери ровно одного игрока. Верни только JSON "
                            + '{"choice":"player_1"} или {"choice":"player_2"}.'
                        ),
                    },
                ],
                "response_format": {
                    "type": "json_schema",
                    "json_schema": {
                        "name": "judge_vote",
                        "strict": True,
                        "schema": {
                            "type": "object",
                            "properties": {
                                "choice": {
                                    "type": "string",
                                    "enum": ["player_1", "player_2"],
                                }
                            },
                            "required": ["choice"],
                            "additionalProperties": False,
                        },
                    },
                },
            }
        )
        return payload

    @staticmethod
    def _usage(value: JsonValue | None) -> dict[str, JsonValue] | None:
        if value is None:
            return None
        if not isinstance(value, dict):
            raise TypeError("usage must be an object")
        for field in _NON_NEGATIVE_USAGE_FIELDS.intersection(value):
            measurement = value[field]
            if (
                not isinstance(measurement, (int, float))
                or isinstance(measurement, bool)
                or not isfinite(measurement)
                or measurement < 0
            ):
                raise ValueError(f"usage.{field} must be a finite non-negative number")
        return value

    @staticmethod
    def _check_http_status(status_code: int) -> None:
        if 200 <= status_code < 300:
            return
        if status_code == 429 or 500 <= status_code < 600:
            raise TransientJudgeError(f"Temporary AITunnel Qwen HTTP {status_code}")
        if status_code in (401, 402, 403, 404):
            raise JudgeConfigurationError(
                "AITunnel rejected credentials, balance, endpoint, or model "
                f"(HTTP {status_code})"
            )
        raise PermanentJudgeTransportError(
            f"AITunnel rejected the Qwen request (HTTP {status_code})"
        )

    @staticmethod
    def _json_value(value: object, *, secret: str) -> JsonValue:
        try:
            detached = json.loads(json.dumps(value, ensure_ascii=False, allow_nan=False))
        except (TypeError, ValueError) as error:
            raise JudgeResponseFormatError(
                "AITunnel response is not safely JSON-serializable"
            ) from error
        return LLMJudge._redact_sensitive_fields(detached, secret=secret)

    @staticmethod
    def _redact_sensitive_fields(value: JsonValue, *, secret: str) -> JsonValue:
        if isinstance(value, dict):
            sanitized: dict[str, JsonValue] = {}
            for key, nested in value.items():
                normalized = key.lower().replace("-", "").replace("_", "")
                sanitized[key] = (
                    "[REDACTED]"
                    if normalized in _SENSITIVE_KEYS
                    else LLMJudge._redact_sensitive_fields(nested, secret=secret)
                )
            return sanitized
        if isinstance(value, list):
            return [
                LLMJudge._redact_sensitive_fields(item, secret=secret)
                for item in value
            ]
        if isinstance(value, str) and secret:
            return value.replace(secret, "[REDACTED]")
        return value


__all__ = ["LLMJudge"]

src/metrics/calculations.py.text:
"""Pure metric calculations over stage-four case aggregates.

Eligibility is decided by :mod:`src.metrics.preparation`.  This module only
filters already eligible aggregates to an explicitly supplied bout scope and
never treats model repeats or human judges as independent cases.
"""

from __future__ import annotations

from dataclasses import dataclass
from itertools import combinations
from statistics import fmean
from typing import Iterable, Sequence

from src.experiment.schemas import Collegium, Player
from src.metrics import COLLEGIA
from src.metrics.aggregation import AggregatedAnalysis, AggregatedCase
from src.metrics.contracts import MetricResult
from src.metrics.preparation import PreparedAnalysis


EMPTY_SCOPE_REASON = "No eligible bout-collegium cases are available"
UNDEFINED_COHEN_REASON = "Cohen's kappa is undefined because expected agreement is 1"
UNDEFINED_FLEISS_REASON = "Fleiss' kappa is undefined because expected agreement is 1"
MISSING_HUMAN_CLASS_REASON = (
    "Macro-F1 is undefined because at least one class is absent from human "
    "majority labels"
)
NO_PROBABILITIES_REASON = (
    "No eligible bout-collegium cases contain every planned provider probability"
)
NO_REPEATS_REASON = "Repeatability requires at least two planned model votes per case"


@dataclass(frozen=True, slots=True)
class AgreementMetrics:
    accuracy: MetricResult
    by_collegium: dict[Collegium, MetricResult]
    cohens_kappa: MetricResult
    macro_f1: MetricResult


@dataclass(frozen=True, slots=True)
class IndividualJudgeMetrics:
    majority_to_individual: MetricResult
    all_pairs: MetricResult


@dataclass(frozen=True, slots=True)
class HumanAgreementMetrics:
    pairwise_agreement: MetricResult
    fleiss_kappa: MetricResult


@dataclass(frozen=True, slots=True)
class RepeatabilityMetrics:
    unanimity_rate: MetricResult
    pairwise_repeatability: MetricResult


@dataclass(frozen=True, slots=True)
class PositionBiasMetrics:
    label_flip_rate: MetricResult
    vote_share_change: MetricResult
    by_collegium: dict[Collegium, tuple[MetricResult, MetricResult]]


@dataclass(frozen=True, slots=True)
class ProbabilityMetrics:
    brier_score: MetricResult
    brier_score_individual: MetricResult
    vote_share_mae: MetricResult
    vote_share_mae_individual: MetricResult
    coverage: MetricResult


@dataclass(frozen=True, slots=True)
class ModelScopeMetrics:
    model_alias: str
    scope_id: str
    bout_ids: tuple[str, ...]
    agreement: AgreementMetrics
    individual_judge: IndividualJudgeMetrics
    repeatability: RepeatabilityMetrics
    probability: ProbabilityMetrics


@dataclass(frozen=True, slots=True)
class PositionScopeMetrics:
    model_alias: str
    scope_id: str
    bout_ids: tuple[str, ...]
    metrics: PositionBiasMetrics


@dataclass(frozen=True, slots=True)
class HumanScopeMetrics:
    scope_id: str
    bout_ids: tuple[str, ...]
    metrics: HumanAgreementMetrics


@dataclass(frozen=True, slots=True)
class CalculatedMetrics:
    model_scopes: tuple[ModelScopeMetrics, ...]
    position_scopes: tuple[PositionScopeMetrics, ...]
    human_scopes: tuple[HumanScopeMetrics, ...]


def _counts(cases: Sequence[AggregatedCase]) -> tuple[int, int]:
    return len({case.bout_id for case in cases}), len(cases)


def _model_vote_count(
    cases: Sequence[AggregatedCase], *, variant: str = "original"
) -> int:
    return sum(
        len(case.original_votes if variant == "original" else case.swapped_votes)
        for case in cases
    )


def _na(
    metric: str,
    cases: Sequence[AggregatedCase],
    reason: str,
    *,
    n_model_votes: int | None = None,
    n_human_votes: int | None = None,
    n_comparisons: int | None = None,
) -> MetricResult:
    n_bouts, n_cases = _counts(cases)
    return MetricResult.not_applicable(
        metric,
        reason,
        n_bouts=n_bouts,
        n_cases=n_cases,
        n_model_votes=n_model_votes,
        n_human_votes=n_human_votes,
        n_comparisons=n_comparisons,
    )


def _mean_result(
    metric: str,
    cases: Sequence[AggregatedCase],
    values: Iterable[float],
    *,
    n_model_votes: int | None = None,
    n_human_votes: int | None = None,
    n_comparisons: int | None = None,
) -> MetricResult:
    n_bouts, n_cases = _counts(cases)
    if not cases:
        return MetricResult.not_applicable(
            metric,
            EMPTY_SCOPE_REASON,
            n_bouts=n_bouts,
            n_cases=n_cases,
            n_model_votes=n_model_votes,
            n_human_votes=n_human_votes,
            n_comparisons=n_comparisons,
        )
    return MetricResult.ok(
        metric,
        fmean(values),
        n_bouts=n_bouts,
        n_cases=n_cases,
        n_model_votes=n_model_votes,
        n_human_votes=n_human_votes,
        n_comparisons=n_comparisons,
    )


def _majorities(case: AggregatedCase) -> tuple[Player, Player]:
    model = case.original_tally.majority
    human = case.human_tally.majority
    if model is None or human is None or not case.original_complete:
        raise ValueError("metrics require complete eligible original cases")
    return model, human


def agreement_rate(cases: Sequence[AggregatedCase]) -> MetricResult:
    """Agreement of model and human majorities at case level."""

    return _mean_result(
        "agreement_rate",
        cases,
        (_majorities(case)[0] == _majorities(case)[1] for case in cases),
        n_model_votes=_model_vote_count(cases),
        n_human_votes=3 * len(cases),
        n_comparisons=len(cases),
    )


def agreement_by_collegium(
    cases: Sequence[AggregatedCase],
) -> dict[Collegium, MetricResult]:
    return {
        collegium: agreement_rate(
            tuple(case for case in cases if case.collegium == collegium)
        ).model_copy(update={"metric": f"agreement_rate_{collegium}"})
        for collegium in COLLEGIA
    }


def cohens_kappa(cases: Sequence[AggregatedCase]) -> MetricResult:
    if not cases:
        return _na(
            "cohens_kappa",
            cases,
            EMPTY_SCOPE_REASON,
            n_model_votes=0,
            n_human_votes=0,
            n_comparisons=0,
        )
    labels = [_majorities(case) for case in cases]
    observed = fmean(model == human for model, human in labels)
    model_p1 = fmean(model == "player_1" for model, _ in labels)
    human_p1 = fmean(human == "player_1" for _, human in labels)
    expected = model_p1 * human_p1 + (1 - model_p1) * (1 - human_p1)
    denominator = 1 - expected
    if denominator == 0:
        return _na(
            "cohens_kappa",
            cases,
            UNDEFINED_COHEN_REASON,
            n_model_votes=_model_vote_count(cases),
            n_human_votes=3 * len(cases),
            n_comparisons=len(cases),
        )
    n_bouts, n_cases = _counts(cases)
    return MetricResult.ok(
        "cohens_kappa",
        (observed - expected) / denominator,
        n_bouts=n_bouts,
        n_cases=n_cases,
        n_model_votes=_model_vote_count(cases),
        n_human_votes=3 * n_cases,
        n_comparisons=n_cases,
    )


def macro_f1(cases: Sequence[AggregatedCase]) -> MetricResult:
    if not cases:
        return _na(
            "macro_f1",
            cases,
            EMPTY_SCOPE_REASON,
            n_model_votes=0,
            n_human_votes=0,
            n_comparisons=0,
        )
    labels = [_majorities(case) for case in cases]
    human_labels = {human for _, human in labels}
    if human_labels != {"player_1", "player_2"}:
        return _na(
            "macro_f1",
            cases,
            MISSING_HUMAN_CLASS_REASON,
            n_model_votes=_model_vote_count(cases),
            n_human_votes=3 * len(cases),
            n_comparisons=len(cases),
        )

    scores = []
    for label in ("player_1", "player_2"):
        true_positive = sum(
            model == label and human == label for model, human in labels
        )
        false_positive = sum(
            model == label and human != label for model, human in labels
        )
        false_negative = sum(
            model != label and human == label for model, human in labels
        )
        denominator = 2 * true_positive + false_positive + false_negative
        if denominator == 0:
            return _na(
                "macro_f1",
                cases,
                f"F1 is undefined for class {label}",
                n_model_votes=_model_vote_count(cases),
                n_human_votes=3 * len(cases),
                n_comparisons=len(cases),
            )
        scores.append(2 * true_positive / denominator)
    n_bouts, n_cases = _counts(cases)
    return MetricResult.ok(
        "macro_f1",
        fmean(scores),
        n_bouts=n_bouts,
        n_cases=n_cases,
        n_model_votes=_model_vote_count(cases),
        n_human_votes=3 * n_cases,
        n_comparisons=n_cases,
    )


def agreement_metrics(cases: Sequence[AggregatedCase]) -> AgreementMetrics:
    return AgreementMetrics(
        accuracy=agreement_rate(cases),
        by_collegium=agreement_by_collegium(cases),
        cohens_kappa=cohens_kappa(cases),
        macro_f1=macro_f1(cases),
    )


def individual_judge_agreement(
    cases: Sequence[AggregatedCase],
) -> IndividualJudgeMetrics:
    for case in cases:
        _majorities(case)
        if len(case.human_votes) != 3 or not case.original_votes:
            raise ValueError("individual agreement requires complete model and human votes")
    model_vote_count = _model_vote_count(cases)
    human_vote_count = 3 * len(cases)
    majority = _mean_result(
        "individual_judge_majority_to_individual",
        cases,
        (
            sum(
                vote.winner == case.original_tally.majority
                for vote in case.human_votes
            )
            / 3
            for case in cases
        ),
        n_model_votes=model_vote_count,
        n_human_votes=human_vote_count,
        n_comparisons=3 * len(cases),
    )
    all_pairs = _mean_result(
        "individual_judge_all_pairs",
        cases,
        (
            sum(
                model.winner == human.winner
                for model in case.original_votes
                for human in case.human_votes
            )
            / (len(case.original_votes) * len(case.human_votes))
            for case in cases
        ),
        n_model_votes=model_vote_count,
        n_human_votes=human_vote_count,
        n_comparisons=sum(
            len(case.original_votes) * len(case.human_votes) for case in cases
        ),
    )
    return IndividualJudgeMetrics(majority, all_pairs)


def _unique_human_cases(
    cases: Sequence[AggregatedCase],
) -> tuple[AggregatedCase, ...]:
    unique: dict[tuple[str, Collegium], AggregatedCase] = {}
    for case in cases:
        key = (case.bout_id, case.collegium)
        previous = unique.setdefault(key, case)
        if tuple(v.winner for v in previous.human_votes) != tuple(
            v.winner for v in case.human_votes
        ):
            raise ValueError("human votes disagree between model aggregates")
    return tuple(unique.values())


def human_human_agreement(
    cases: Sequence[AggregatedCase],
) -> HumanAgreementMetrics:
    cases = _unique_human_cases(cases)
    for case in cases:
        if len(case.human_votes) != 3:
            raise ValueError("human agreement requires complete vote triples")
    pairwise = _mean_result(
        "human_pairwise_agreement",
        cases,
        (
            sum(
                left.winner == right.winner
                for left, right in combinations(case.human_votes, 2)
            )
            / 3
            for case in cases
        ),
        n_human_votes=3 * len(cases),
        n_comparisons=3 * len(cases),
    )
    if not cases:
        fleiss = _na(
            "fleiss_kappa",
            cases,
            EMPTY_SCOPE_REASON,
            n_human_votes=0,
            n_comparisons=0,
        )
    else:
        n_raters = 3
        observed = fmean(
            (
                case.human_tally.player_1**2
                + case.human_tally.player_2**2
                - n_raters
            )
            / (n_raters * (n_raters - 1))
            for case in cases
        )
        total_votes = n_raters * len(cases)
        p1 = sum(case.human_tally.player_1 for case in cases) / total_votes
        expected = p1**2 + (1 - p1) ** 2
        denominator = 1 - expected
        if denominator == 0:
            fleiss = _na(
                "fleiss_kappa",
                cases,
                UNDEFINED_FLEISS_REASON,
                n_human_votes=total_votes,
                n_comparisons=3 * len(cases),
            )
        else:
            n_bouts, n_cases = _counts(cases)
            fleiss = MetricResult.ok(
                "fleiss_kappa",
                (observed - expected) / denominator,
                n_bouts=n_bouts,
                n_cases=n_cases,
                n_human_votes=total_votes,
                n_comparisons=3 * n_cases,
            )
    return HumanAgreementMetrics(pairwise, fleiss)


def repeatability(
    cases: Sequence[AggregatedCase], *, variant: str = "original"
) -> RepeatabilityMetrics:
    if variant not in {"original", "swapped"}:
        raise ValueError("variant must be 'original' or 'swapped'")

    def votes_for(case: AggregatedCase):
        votes = case.original_votes if variant == "original" else case.swapped_votes
        complete = (
            case.original_complete
            if variant == "original"
            else case.swapped_complete
        )
        if not complete or not votes:
            raise ValueError(f"repeatability requires complete {variant} votes")
        return votes

    vote_groups = [votes_for(case) for case in cases]
    suffix = "" if variant == "original" else "_swapped"
    n_model_votes = sum(len(votes) for votes in vote_groups)
    if vote_groups and any(len(votes) < 2 for votes in vote_groups):
        return RepeatabilityMetrics(
            _na(
                f"unanimity_rate{suffix}", cases, NO_REPEATS_REASON,
                n_model_votes=n_model_votes, n_comparisons=0,
            ),
            _na(
                f"pairwise_repeatability{suffix}", cases, NO_REPEATS_REASON,
                n_model_votes=n_model_votes, n_comparisons=0,
            ),
        )
    comparison_count = sum(
        len(votes) * (len(votes) - 1) // 2 for votes in vote_groups
    )
    unanimity = _mean_result(
        f"unanimity_rate{suffix}",
        cases,
        (len({vote.winner for vote in votes}) == 1 for votes in vote_groups),
        n_model_votes=n_model_votes,
    )
    pairwise = _mean_result(
        f"pairwise_repeatability{suffix}",
        cases,
        (
            sum(left.winner == right.winner for left, right in combinations(votes, 2))
            / (len(votes) * (len(votes) - 1) / 2)
            for votes in vote_groups
        ),
        n_model_votes=n_model_votes,
        n_comparisons=comparison_count,
    )
    return RepeatabilityMetrics(unanimity, pairwise)


def _position_pair(
    cases: Sequence[AggregatedCase], metric_suffix: str = ""
) -> tuple[MetricResult, MetricResult]:
    for case in cases:
        if (
            not case.position_eligible
            or case.position_winner_changed is None
            or case.position_vote_share_change is None
        ):
            raise ValueError("position metrics require position-eligible cases")
    flips = _mean_result(
        f"label_flip_rate{metric_suffix}",
        cases,
        (case.position_winner_changed for case in cases),
        n_model_votes=_model_vote_count(cases) + _model_vote_count(cases, variant="swapped"),
        n_comparisons=len(cases),
    )
    shares = _mean_result(
        f"vote_share_change{metric_suffix}",
        cases,
        (case.position_vote_share_change for case in cases),
        n_model_votes=_model_vote_count(cases) + _model_vote_count(cases, variant="swapped"),
        n_comparisons=len(cases),
    )
    return flips, shares


def position_bias(cases: Sequence[AggregatedCase]) -> PositionBiasMetrics:
    flips, shares = _position_pair(cases)
    by_collegium = {
        collegium: _position_pair(
            tuple(case for case in cases if case.collegium == collegium),
            f"_{collegium}",
        )
        for collegium in COLLEGIA
    }
    return PositionBiasMetrics(flips, shares, by_collegium)


def probability_metrics(cases: Sequence[AggregatedCase]) -> ProbabilityMetrics:
    for case in cases:
        _majorities(case)
    eligible = tuple(
        case
        for case in cases
        if case.original_probabilities
        and all(value is not None for value in case.original_probabilities)
    )
    n_bouts, n_cases = _counts(cases)
    if cases:
        coverage = MetricResult.ok(
            "probability_coverage",
            len(eligible) / len(cases),
            n_bouts=n_bouts,
            n_cases=n_cases,
            n_model_votes=_model_vote_count(eligible),
        )
    else:
        coverage = MetricResult.not_applicable(
            "probability_coverage",
            EMPTY_SCOPE_REASON,
            n_bouts=0,
            n_cases=0,
            n_model_votes=0,
        )

    if not eligible:
        def unavailable(metric: str) -> MetricResult:
            return MetricResult.not_applicable(
                metric,
                NO_PROBABILITIES_REASON,
                n_bouts=0,
                n_cases=0,
                n_model_votes=0,
                n_human_votes=0,
                n_comparisons=0,
            )

        return ProbabilityMetrics(
            unavailable("brier_score"),
            unavailable("brier_score_individual"),
            unavailable("vote_share_mae"),
            unavailable("vote_share_mae_individual"),
            coverage,
        )

    def probabilities(case: AggregatedCase) -> tuple[float, ...]:
        values = case.original_probabilities
        assert values and all(value is not None for value in values)
        return values  # type: ignore[return-value]

    def target(case: AggregatedCase) -> int:
        return int(case.human_tally.majority == "player_1")

    def human_share(case: AggregatedCase) -> float:
        share = case.human_tally.player_1_share
        assert share is not None
        return share

    def metric(
        name: str, values: Iterable[float], *, individual: bool = False
    ) -> MetricResult:
        return _mean_result(
            name,
            eligible,
            values,
            n_model_votes=_model_vote_count(eligible),
            n_human_votes=3 * len(eligible),
            n_comparisons=(
                _model_vote_count(eligible) if individual else len(eligible)
            ),
        )

    return ProbabilityMetrics(
        metric(
            "brier_score",
            ((fmean(probabilities(case)) - target(case)) ** 2 for case in eligible),
        ),
        metric(
            "brier_score_individual",
            (
                fmean((value - target(case)) ** 2 for value in probabilities(case))
                for case in eligible
            ),
            individual=True,
        ),
        metric(
            "vote_share_mae",
            (
                abs(fmean(probabilities(case)) - human_share(case))
                for case in eligible
            ),
        ),
        metric(
            "vote_share_mae_individual",
            (
                fmean(abs(value - human_share(case)) for value in probabilities(case))
                for case in eligible
            ),
            individual=True,
        ),
        coverage,
    )


def _select(
    cases: Sequence[AggregatedCase],
    *,
    model_alias: str | None = None,
    bout_ids: Sequence[str],
) -> tuple[AggregatedCase, ...]:
    allowed = set(bout_ids)
    return tuple(
        case
        for case in cases
        if case.bout_id in allowed
        and (model_alias is None or case.model_alias == model_alias)
    )


def calculate_metrics(
    prepared: PreparedAnalysis, aggregated: AggregatedAnalysis
) -> CalculatedMetrics:
    """Calculate every stage-five metric on all mandated scopes."""

    model_results: list[ModelScopeMetrics] = []
    position_results: list[PositionScopeMetrics] = []
    for model_alias in prepared.model_aliases:
        for scope in (prepared.model_scope(model_alias), prepared.common_scope):
            cases = _select(
                aggregated.original_cases,
                model_alias=model_alias,
                bout_ids=scope.bout_ids,
            )
            scope_id = (
                scope.scope_id
                if scope.kind == "model"
                else f"common:{model_alias}"
            )
            model_results.append(
                ModelScopeMetrics(
                    model_alias=model_alias,
                    scope_id=scope_id,
                    bout_ids=scope.bout_ids,
                    agreement=agreement_metrics(cases),
                    individual_judge=individual_judge_agreement(cases),
                    repeatability=repeatability(cases),
                    probability=probability_metrics(cases),
                )
            )
        for scope in (
            prepared.position_scope(model_alias),
            prepared.position_common_scope,
        ):
            cases = _select(
                aggregated.position_cases,
                model_alias=model_alias,
                bout_ids=scope.bout_ids,
            )
            scope_id = (
                scope.scope_id
                if scope.kind == "position"
                else f"position:common:{model_alias}"
            )
            position_results.append(
                PositionScopeMetrics(
                    model_alias=model_alias,
                    scope_id=scope_id,
                    bout_ids=scope.bout_ids,
                    metrics=position_bias(cases),
                )
            )

    all_human_cases = _unique_human_cases(aggregated.case_diagnostics)
    human_scope_specs = [("all_humans", prepared.selected_bout_ids)]
    human_scope_specs.extend(
        (f"humans:model:{model_alias}", prepared.model_scope(model_alias).bout_ids)
        for model_alias in prepared.model_aliases
    )
    if len(prepared.model_aliases) > 1:
        human_scope_specs.append(("humans:common", prepared.common_scope.bout_ids))
    human_results = tuple(
        HumanScopeMetrics(
            scope_id=scope_id,
            bout_ids=tuple(bout_ids),
            metrics=human_human_agreement(
                _select(all_human_cases, bout_ids=bout_ids)
            ),
        )
        for scope_id, bout_ids in human_scope_specs
    )
    return CalculatedMetrics(
        model_scopes=tuple(model_results),
        position_scopes=tuple(position_results),
        human_scopes=human_results,
    )


__all__ = [
    "AgreementMetrics",
    "CalculatedMetrics",
    "HumanAgreementMetrics",
    "HumanScopeMetrics",
    "IndividualJudgeMetrics",
    "ModelScopeMetrics",
    "PositionBiasMetrics",
    "PositionScopeMetrics",
    "ProbabilityMetrics",
    "RepeatabilityMetrics",
    "agreement_by_collegium",
    "agreement_metrics",
    "agreement_rate",
    "calculate_metrics",
    "cohens_kappa",
    "human_human_agreement",
    "individual_judge_agreement",
    "macro_f1",
    "position_bias",
    "probability_metrics",
    "repeatability",
]

src/metrics/contracts.py.text:
"""Strict internal contracts shared by metrics pipeline layers."""

from __future__ import annotations

from math import isfinite
from typing import Annotated, Literal, Self

from pydantic import BaseModel, ConfigDict, Field, StringConstraints, model_validator

from src.experiment.schemas import Collegium, Player, Probability, Variant


NonEmptyString = Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]
PositiveOrdinal = Annotated[int, Field(strict=True, ge=1, le=3)]
NonNegativeCount = Annotated[int, Field(strict=True, ge=0)]
VoteSource = Literal["human", "model"]
MetricStatus = Literal["ok", "not_applicable"]
IntervalUnit = Literal["proportion", "percentage_points", "coefficient"]
Alternative = Literal["greater", "two_sided"]
HypothesisStatus = Literal["confirmed", "not_confirmed", "not_evaluable"]
ScopeKind = Literal[
    "model",
    "common",
    "position",
    "position_common",
    "probability",
]


class FrozenStrictModel(BaseModel):
    """Immutable model that rejects coercion and unknown fields."""

    model_config = ConfigDict(extra="forbid", strict=True, frozen=True)


class NormalizedVote(FrozenStrictModel):
    """One human or model vote normalized to the original player labels."""

    source: VoteSource
    bout_id: NonEmptyString
    collegium: Collegium
    ordinal: PositiveOrdinal
    winner: Player
    model_alias: NonEmptyString | None = None
    variant: Variant | None = None
    probability_player_1: Probability | None = None

    @model_validator(mode="after")
    def check_source_fields(self) -> Self:
        if self.source == "human":
            if self.model_alias is not None or self.variant is not None:
                raise ValueError("human votes cannot have model_alias or variant")
            if self.probability_player_1 is not None:
                raise ValueError("human votes cannot have provider probabilities")
        elif self.model_alias is None or self.variant is None:
            raise ValueError("model votes require model_alias and variant")
        return self


class BoutCollegiumCase(FrozenStrictModel):
    """A complete ``bout x collegium`` comparison for one model and variant."""

    bout_id: NonEmptyString
    collegium: Collegium
    model_alias: NonEmptyString
    variant: Variant
    model_votes: Annotated[tuple[NormalizedVote, ...], Field(min_length=1, max_length=3)]
    human_votes: Annotated[tuple[NormalizedVote, ...], Field(min_length=3, max_length=3)]

    @model_validator(mode="after")
    def check_votes_match_case(self) -> Self:
        for source, votes in (("model", self.model_votes), ("human", self.human_votes)):
            expected_ordinals = (
                list(range(1, len(votes) + 1)) if source == "model" else [1, 2, 3]
            )
            if sorted(vote.ordinal for vote in votes) != expected_ordinals:
                raise ValueError(
                    f"{source}_votes must contain consecutive ordinals starting at 1"
                )
            for vote in votes:
                if (
                    vote.source != source
                    or vote.bout_id != self.bout_id
                    or vote.collegium != self.collegium
                ):
                    raise ValueError(f"{source}_votes do not match the case identity")
                if source == "model" and (
                    vote.model_alias != self.model_alias or vote.variant != self.variant
                ):
                    raise ValueError("model_votes do not match the model or variant")
        return self


class MetricScope(FrozenStrictModel):
    """Named, auditable set of bouts used as a metric denominator."""

    scope_id: NonEmptyString
    kind: ScopeKind
    bout_ids: tuple[NonEmptyString, ...]
    model_alias: NonEmptyString | None = None

    @model_validator(mode="after")
    def check_scope(self) -> Self:
        if len(set(self.bout_ids)) != len(self.bout_ids):
            raise ValueError("scope bout_ids must be unique")
        if self.kind in {"model", "position", "probability"}:
            if self.model_alias is None:
                raise ValueError(f"{self.kind} scope requires model_alias")
        elif self.model_alias is not None:
            raise ValueError(f"{self.kind} scope cannot belong to one model")
        return self

    @property
    def n_bouts(self) -> int:
        return len(self.bout_ids)


class Exclusion(FrozenStrictModel):
    """Reason why a bout or collegium case is absent from a calculation."""

    scope_id: NonEmptyString
    bout_id: NonEmptyString
    reason_code: NonEmptyString
    reason: NonEmptyString
    model_alias: NonEmptyString | None = None
    variant: Variant | None = None
    collegium: Collegium | None = None
    metric: NonEmptyString | None = None
    actual_count: NonNegativeCount | None = None
    required_count: NonNegativeCount | None = None


class ProbabilityCase(FrozenStrictModel):
    """One complete ``bout x collegium`` case with three real probabilities."""

    bout_id: NonEmptyString
    collegium: Collegium


class ProbabilityScope(FrozenStrictModel):
    """Auditable case-level denominator for probabilistic metrics."""

    scope_id: NonEmptyString
    base_scope_id: NonEmptyString
    model_alias: NonEmptyString
    cases: tuple[ProbabilityCase, ...]

    @model_validator(mode="after")
    def check_cases(self) -> Self:
        identities = [(case.bout_id, case.collegium) for case in self.cases]
        if len(set(identities)) != len(identities):
            raise ValueError("probability scope cases must be unique")
        return self

    @property
    def bout_ids(self) -> tuple[str, ...]:
        return tuple(dict.fromkeys(case.bout_id for case in self.cases))

    @property
    def n_bouts(self) -> int:
        return len(self.bout_ids)

    @property
    def n_cases(self) -> int:
        return len(self.cases)


class MetricResult(FrozenStrictModel):
    """One finite metric value or an explicit, explained N/A result."""

    metric: NonEmptyString
    status: MetricStatus
    value: float | None
    n_bouts: NonNegativeCount
    n_cases: NonNegativeCount
    n_model_votes: NonNegativeCount | None = None
    n_human_votes: NonNegativeCount | None = None
    n_comparisons: NonNegativeCount | None = None
    reason: NonEmptyString | None = None

    @model_validator(mode="after")
    def check_result(self) -> Self:
        if self.status == "ok":
            if self.value is None or not isfinite(self.value):
                raise ValueError("ok metric result requires a finite value")
            if self.reason is not None:
                raise ValueError("ok metric result cannot have an N/A reason")
        else:
            if self.value is not None:
                raise ValueError("not_applicable metric result must have value=null")
            if self.reason is None:
                raise ValueError("not_applicable metric result requires a reason")
        return self

    @classmethod
    def ok(
        cls,
        metric: str,
        value: float,
        *,
        n_bouts: int,
        n_cases: int,
        n_model_votes: int | None = None,
        n_human_votes: int | None = None,
        n_comparisons: int | None = None,
    ) -> Self:
        return cls(
            metric=metric,
            status="ok",
            value=value,
            n_bouts=n_bouts,
            n_cases=n_cases,
            n_model_votes=n_model_votes,
            n_human_votes=n_human_votes,
            n_comparisons=n_comparisons,
        )

    @classmethod
    def not_applicable(
        cls,
        metric: str,
        reason: str,
        *,
        n_bouts: int = 0,
        n_cases: int = 0,
        n_model_votes: int | None = None,
        n_human_votes: int | None = None,
        n_comparisons: int | None = None,
    ) -> Self:
        return cls(
            metric=metric,
            status="not_applicable",
            value=None,
            reason=reason,
            n_bouts=n_bouts,
            n_cases=n_cases,
            n_model_votes=n_model_votes,
            n_human_votes=n_human_votes,
            n_comparisons=n_comparisons,
        )


class ConfidenceIntervalResult(FrozenStrictModel):
    """A finite percentile interval or an explicit, explained N/A result."""

    metric: NonEmptyString
    status: MetricStatus
    lower: float | None
    upper: float | None
    unit: IntervalUnit
    confidence_level: float = Field(strict=True, gt=0, lt=1)
    replications: NonNegativeCount
    valid_replications: NonNegativeCount | None = None
    seed: int
    n_bouts: NonNegativeCount
    n_cases: NonNegativeCount
    reason: NonEmptyString | None = None
    warning: NonEmptyString | None = None

    @model_validator(mode="after")
    def check_interval(self) -> Self:
        if (
            self.valid_replications is not None
            and self.valid_replications > self.replications
        ):
            raise ValueError("valid replications cannot exceed requested replications")
        if self.status == "ok":
            if (
                self.lower is None
                or self.upper is None
                or not isfinite(self.lower)
                or not isfinite(self.upper)
                or self.lower > self.upper
            ):
                raise ValueError("ok confidence interval requires finite ordered bounds")
            if self.reason is not None:
                raise ValueError("ok confidence interval cannot have an N/A reason")
        else:
            if self.lower is not None or self.upper is not None:
                raise ValueError("not_applicable interval must have null bounds")
            if self.reason is None:
                raise ValueError("not_applicable interval requires a reason")
        return self


class InferenceTestResult(FrozenStrictModel):
    """One pre-specified permutation test in the H1-H3 family."""

    test_id: NonEmptyString
    hypothesis_id: Literal["H1", "H2", "H3"]
    metric: NonEmptyString
    scope_id: NonEmptyString
    null_hypothesis: NonEmptyString
    alternative: Alternative
    status: MetricStatus
    effect: float | None
    raw_p_value: float | None = Field(default=None, ge=0, le=1)
    adjusted_p_value: float | None = Field(default=None, ge=0, le=1)
    alpha: float = Field(strict=True, gt=0, lt=1)
    method: NonEmptyString
    exact: bool
    permutations: NonNegativeCount
    seed: int
    n_bouts: NonNegativeCount
    n_cases: NonNegativeCount
    reason: NonEmptyString | None = None

    @model_validator(mode="after")
    def check_test(self) -> Self:
        if self.status == "ok":
            if self.effect is None or not isfinite(self.effect):
                raise ValueError("ok inference test requires a finite effect")
            if self.raw_p_value is None or self.adjusted_p_value is None:
                raise ValueError("ok inference test requires raw and adjusted p-values")
            if self.reason is not None:
                raise ValueError("ok inference test cannot have an N/A reason")
        else:
            if any(
                value is not None
                for value in (self.effect, self.raw_p_value, self.adjusted_p_value)
            ):
                raise ValueError("not_applicable inference test must have null results")
            if self.reason is None:
                raise ValueError("not_applicable inference test requires a reason")
        return self


class HypothesisDecision(FrozenStrictModel):
    """Pre-specified decision derived only from Holm-adjusted primary tests."""

    decision_id: NonEmptyString
    hypothesis_id: Literal["H1", "H2", "H3"]
    model_alias: NonEmptyString | None = None
    status: HypothesisStatus
    test_ids: tuple[NonEmptyString, ...]
    conclusion: NonEmptyString

src/metrics/loading.py.text:
"""Read-only loading and provenance capture for one metrics calculation run."""

from __future__ import annotations

from dataclasses import dataclass
from hashlib import sha256
import json
from pathlib import Path
from typing import Literal

from pydantic import ValidationError

from src.experiment.config import ExperimentConfig
from src.experiment.schemas import CallRecord, TranscriptSchema, load_transcript
from src.experiment.storage import RunMetadata, RunStorage, StorageError


DatasetName = Literal["pilot", "main"]


class AnalysisInputError(RuntimeError):
    """A selected local input cannot be read or violates its persisted contract."""


@dataclass(frozen=True, slots=True)
class InputFile:
    """A file actually used by the analysis and its content digest."""

    path: Path
    sha256: str


@dataclass(frozen=True, slots=True)
class SelectedTranscript:
    """One selected, fully validated transcript together with its source file."""

    path: Path
    transcript: TranscriptSchema


@dataclass(frozen=True, slots=True)
class AnalysisInputs:
    """Validated scientific inputs for exactly one explicitly selected run."""

    dataset: DatasetName
    run: RunStorage
    latest_records: tuple[CallRecord, ...]
    transcripts: tuple[SelectedTranscript, ...]
    input_files: tuple[InputFile, ...]

    @property
    def metadata(self) -> RunMetadata:
        return self.run.metadata


def file_sha256(path: Path) -> str:
    """Hash the exact bytes of one input file."""

    digest = sha256()
    try:
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError as error:
        raise AnalysisInputError(f"Cannot hash input file {path}: {error}") from error
    return digest.hexdigest()


def _configured_paths(
    config: ExperimentConfig,
    dataset: DatasetName,
) -> tuple[Path, Path]:
    dataset_dir = getattr(config.datasets, dataset)
    results_root = getattr(config.results, dataset)
    if not dataset_dir.is_dir():
        raise AnalysisInputError(
            f"Selected dataset directory does not exist: {dataset_dir}"
        )
    if not results_root.is_dir():
        raise AnalysisInputError(
            f"Selected results directory does not exist: {results_root}"
        )
    return dataset_dir, results_root


def _json_files(directory: Path) -> tuple[Path, ...]:
    try:
        return tuple(
            sorted(
                (
                    path
                    for path in directory.iterdir()
                    if path.is_file() and path.suffix.lower() == ".json"
                ),
                key=lambda path: (path.name.casefold(), path.name),
            )
        )
    except OSError as error:
        raise AnalysisInputError(
            f"Cannot scan selected dataset directory {directory}: {error}"
        ) from error


def _read_root_id(path: Path) -> str:
    """Read only enough structure to index a transcript candidate by root ``id``."""

    try:
        with path.open("r", encoding="utf-8") as stream:
            payload = json.load(stream)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise AnalysisInputError(f"Cannot index transcript {path}: {error}") from error
    if not isinstance(payload, dict):
        raise AnalysisInputError(f"Cannot index transcript {path}: root must be an object")
    bout_id = payload.get("id")
    if not isinstance(bout_id, str) or not bout_id.strip():
        raise AnalysisInputError(
            f"Cannot index transcript {path}: root id must be a non-empty string"
        )
    return bout_id.strip()


def load_selected_transcripts(
    directory: Path,
    selected_bout_ids: tuple[str, ...],
) -> tuple[SelectedTranscript, ...]:
    """Index files by root ID, then fully validate only selected transcripts."""

    selected = set(selected_bout_ids)
    paths_by_id: dict[str, list[Path]] = {bout_id: [] for bout_id in selected_bout_ids}
    for path in _json_files(directory):
        bout_id = _read_root_id(path)
        if bout_id in selected:
            paths_by_id[bout_id].append(path)

    problems = []
    for bout_id in selected_bout_ids:
        count = len(paths_by_id[bout_id])
        if count != 1:
            problems.append(f"id {bout_id!r}: expected exactly one file, found {count}")
    if problems:
        raise AnalysisInputError(
            "Selected transcripts cannot be matched by root id: " + "; ".join(problems)
        )

    loaded = []
    for bout_id in selected_bout_ids:
        path = paths_by_id[bout_id][0]
        try:
            transcript = load_transcript(path)
        except (OSError, UnicodeError, ValidationError) as error:
            raise AnalysisInputError(
                f"Invalid selected transcript {path}: {error}"
            ) from error
        if transcript.id != bout_id:  # defensive: the same schema field built the index
            raise AnalysisInputError(
                f"Selected transcript id changed while reading {path}"
            )
        loaded.append(SelectedTranscript(path=path, transcript=transcript))
    return tuple(loaded)


def load_analysis_inputs(
    config: ExperimentConfig,
    dataset: DatasetName,
    run_id: str,
) -> AnalysisInputs:
    """Load exactly one run and its selected current transcripts without writes."""

    dataset_dir, results_root = _configured_paths(config, dataset)
    try:
        run = RunStorage.open_read_only(results_root, run_id)
    except StorageError as error:
        raise AnalysisInputError(f"Cannot open selected run: {error}") from error

    if run.metadata.mode != dataset or run.metadata.dataset != dataset:
        raise AnalysisInputError(
            "Selected run metadata does not match the configured dataset directory: "
            f"requested {dataset!r}, metadata mode={run.metadata.mode!r}, "
            f"dataset={run.metadata.dataset!r}"
        )

    transcripts = load_selected_transcripts(
        dataset_dir,
        run.metadata.selected_bout_ids,
    )
    source_paths = (
        run.metadata_path,
        run.calls_path,
        *(item.path for item in transcripts),
    )
    input_files = tuple(
        InputFile(path=path, sha256=file_sha256(path)) for path in source_paths
    )
    return AnalysisInputs(
        dataset=dataset,
        run=run,
        latest_records=run.latest_records,
        transcripts=transcripts,
        input_files=input_files,
    )


# Concise alias for callers that already operate inside the metrics package.
load_inputs = load_analysis_inputs


__all__ = [
    "AnalysisInputError",
    "AnalysisInputs",
    "InputFile",
    "SelectedTranscript",
    "file_sha256",
    "load_analysis_inputs",
    "load_inputs",
    "load_selected_transcripts",
]

src/metrics/preparation.py.text:
"""Normalize saved votes and build auditable eligibility scopes.

This layer deliberately performs no metric aggregation.  Its output is the
single source of truth for which whole bouts and collegium cases later metric
functions may use.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Mapping

from src.experiment.schemas import CallRecord, Collegium, Player, Variant
from src.experiment.storage import PlannedTaskIdentity
from src.metrics import COLLEGIA
from src.metrics.contracts import (
    BoutCollegiumCase,
    Exclusion,
    MetricScope,
    NormalizedVote,
    ProbabilityCase,
    ProbabilityScope,
)
from src.metrics.loading import AnalysisInputs


HUMAN_COLLEGIUM_KEYS: Mapping[str, Collegium] = {
    "Нанимающаяся на работу": "hiring",
    "Отправляющая на переговоры": "negotiation",
    "Доверяющая собственность": "ownership",
}
VARIANTS: tuple[Variant, ...] = ("original", "swapped")
TaskIdentity = tuple[str, str, Variant, Collegium, int]
BlockIdentity = tuple[str, str, Variant]


@dataclass(frozen=True, slots=True)
class PreparedBlock:
    """Completeness and normalized successful votes for one model block."""

    model_alias: str
    bout_id: str
    variant: Variant
    planned_count: int
    successful_count: int
    required_count: int
    complete: bool
    votes: tuple[NormalizedVote, ...]
    cases: tuple[BoutCollegiumCase, ...]


@dataclass(frozen=True, slots=True)
class PreparedAnalysis:
    """Normalized data and every eligibility denominator required downstream."""

    selected_bout_ids: tuple[str, ...]
    model_aliases: tuple[str, ...]
    human_votes: tuple[NormalizedVote, ...]
    blocks: tuple[PreparedBlock, ...]
    model_scopes: tuple[MetricScope, ...]
    common_scope: MetricScope
    position_scopes: tuple[MetricScope, ...]
    position_common_scope: MetricScope
    probability_scopes: tuple[ProbabilityScope, ...]
    exclusions: tuple[Exclusion, ...]

    def block(
        self, model_alias: str, bout_id: str, variant: Variant
    ) -> PreparedBlock:
        for block in self.blocks:
            if (
                block.model_alias == model_alias
                and block.bout_id == bout_id
                and block.variant == variant
            ):
                return block
        raise KeyError((model_alias, bout_id, variant))

    def model_scope(self, model_alias: str) -> MetricScope:
        return _find_model_item(self.model_scopes, model_alias)

    def position_scope(self, model_alias: str) -> MetricScope:
        return _find_model_item(self.position_scopes, model_alias)

    def probability_scope(
        self, model_alias: str, *, common: bool = False
    ) -> ProbabilityScope:
        base = "common" if common else f"model:{model_alias}"
        for scope in self.probability_scopes:
            if scope.model_alias == model_alias and scope.base_scope_id == base:
                return scope
        raise KeyError((model_alias, base))


def _find_model_item(items, model_alias: str):
    for item in items:
        if item.model_alias == model_alias:
            return item
    raise KeyError(model_alias)


def _task_identity(task: PlannedTaskIdentity) -> TaskIdentity:
    return (
        task.model_alias,
        task.bout_id,
        task.variant,
        task.collegium,
        task.repeat_index,
    )


def _record_identity(record: CallRecord) -> TaskIdentity:
    task = record.task
    return (
        task.model_alias,
        task.bout_id,
        task.variant,
        task.collegium,
        task.repeat_index,
    )


def _original_player(player: Player, variant: Variant) -> Player:
    if variant == "original":
        return player
    return "player_2" if player == "player_1" else "player_1"


def _human_votes(inputs: AnalysisInputs) -> tuple[NormalizedVote, ...]:
    normalized: list[NormalizedVote] = []
    for selected in inputs.transcripts:
        grouped: dict[Collegium, list] = {collegium: [] for collegium in COLLEGIA}
        for vote in selected.transcript.human_votes:
            grouped[HUMAN_COLLEGIUM_KEYS[vote.collegia]].append(vote)
        for collegium in COLLEGIA:
            for ordinal, vote in enumerate(
                sorted(grouped[collegium], key=lambda item: item.judge_id), start=1
            ):
                normalized.append(
                    NormalizedVote(
                        source="human",
                        bout_id=selected.transcript.id,
                        collegium=collegium,
                        ordinal=ordinal,
                        winner=vote.decision,
                    )
                )
    return tuple(normalized)


def _model_vote(record: CallRecord) -> NormalizedVote:
    # Only callers that selected a successful latest revision may enter here.
    assert record.response is not None
    task = record.task
    probability = record.response.probabilities
    probability_player_1 = None
    if probability is not None:
        probability_player_1 = (
            probability.player_1
            if task.variant == "original"
            else probability.player_2
        )
    return NormalizedVote(
        source="model",
        bout_id=task.bout_id,
        collegium=task.collegium,
        ordinal=task.repeat_index,
        winner=_original_player(record.response.winner, task.variant),
        model_alias=task.model_alias,
        variant=task.variant,
        probability_player_1=probability_player_1,
    )


def _scope_bouts(
    selected_bout_ids: tuple[str, ...], complete: Mapping[str, set[str]]
) -> tuple[str, ...]:
    if not complete:
        return ()
    intersection = set.intersection(*(set(ids) for ids in complete.values()))
    return tuple(bout_id for bout_id in selected_bout_ids if bout_id in intersection)


def prepare_analysis_data(inputs: AnalysisInputs) -> PreparedAnalysis:
    """Normalize latest revisions and construct all stage-three scopes."""

    metadata = inputs.metadata
    selected_bout_ids = metadata.selected_bout_ids
    model_aliases = tuple(model.alias for model in metadata.models)
    planned = {_task_identity(task) for task in metadata.planned_tasks}
    repeat_indices = tuple(
        sorted({task.repeat_index for task in metadata.planned_tasks})
    )
    if repeat_indices not in {(1,), (1, 2, 3)}:
        raise ValueError(
            "planned model votes must use repeat indices (1,) or (1, 2, 3)"
        )
    required_votes_per_block = len(COLLEGIA) * len(repeat_indices)
    latest = {_record_identity(record): record for record in inputs.latest_records}
    humans = _human_votes(inputs)
    humans_by_case = {
        (bout_id, collegium): tuple(
            vote
            for vote in humans
            if vote.bout_id == bout_id and vote.collegium == collegium
        )
        for bout_id in selected_bout_ids
        for collegium in COLLEGIA
    }

    blocks: list[PreparedBlock] = []
    block_index: dict[BlockIdentity, PreparedBlock] = {}
    for model_alias in model_aliases:
        for bout_id in selected_bout_ids:
            for variant in VARIANTS:
                expected = {
                    (model_alias, bout_id, variant, collegium, repeat_index)
                    for collegium in COLLEGIA
                    for repeat_index in repeat_indices
                }
                planned_count = len(expected & planned)
                records = [
                    latest[identity]
                    for identity in expected
                    if identity in latest and latest[identity].status == "success"
                ]
                votes = tuple(
                    sorted(
                        (_model_vote(record) for record in records),
                        key=lambda vote: (COLLEGIA.index(vote.collegium), vote.ordinal),
                    )
                )
                complete = (
                    planned_count == required_votes_per_block
                    and len(votes) == required_votes_per_block
                )
                cases: tuple[BoutCollegiumCase, ...] = ()
                if complete:
                    cases = tuple(
                        BoutCollegiumCase(
                            bout_id=bout_id,
                            collegium=collegium,
                            model_alias=model_alias,
                            variant=variant,
                            model_votes=tuple(
                                vote for vote in votes if vote.collegium == collegium
                            ),
                            human_votes=humans_by_case[(bout_id, collegium)],
                        )
                        for collegium in COLLEGIA
                    )
                block = PreparedBlock(
                    model_alias=model_alias,
                    bout_id=bout_id,
                    variant=variant,
                    planned_count=planned_count,
                    successful_count=len(votes),
                    required_count=required_votes_per_block,
                    complete=complete,
                    votes=votes,
                    cases=cases,
                )
                blocks.append(block)
                block_index[(model_alias, bout_id, variant)] = block

    complete_original: dict[str, set[str]] = {}
    complete_position: dict[str, set[str]] = {}
    model_scopes: list[MetricScope] = []
    position_scopes: list[MetricScope] = []
    exclusions: list[Exclusion] = []
    for model_alias in model_aliases:
        originals = {
            bout_id
            for bout_id in selected_bout_ids
            if block_index[(model_alias, bout_id, "original")].complete
        }
        positions = {
            bout_id
            for bout_id in originals
            if block_index[(model_alias, bout_id, "swapped")].complete
        }
        complete_original[model_alias] = originals
        complete_position[model_alias] = positions
        model_scopes.append(
            MetricScope(
                scope_id=f"model:{model_alias}",
                kind="model",
                model_alias=model_alias,
                bout_ids=tuple(b for b in selected_bout_ids if b in originals),
            )
        )
        position_scopes.append(
            MetricScope(
                scope_id=f"position:{model_alias}",
                kind="position",
                model_alias=model_alias,
                bout_ids=tuple(b for b in selected_bout_ids if b in positions),
            )
        )
        for bout_id in selected_bout_ids:
            original = block_index[(model_alias, bout_id, "original")]
            if not original.complete:
                exclusions.append(
                    _block_exclusion(
                        "model:" + model_alias,
                        original,
                        "incomplete_original",
                    )
                )
            if bout_id not in positions:
                original_ok = original.complete
                deficient = block_index[
                    (model_alias, bout_id, "swapped" if original_ok else "original")
                ]
                code = "incomplete_swapped" if original_ok else "incomplete_original"
                exclusions.append(
                    _block_exclusion("position:" + model_alias, deficient, code)
                )

    common_bouts = _scope_bouts(selected_bout_ids, complete_original)
    position_common_bouts = _scope_bouts(selected_bout_ids, complete_position)
    common_scope = MetricScope(
        scope_id="common", kind="common", bout_ids=common_bouts
    )
    position_common_scope = MetricScope(
        scope_id="position:common",
        kind="position_common",
        bout_ids=position_common_bouts,
    )

    for model_alias in model_aliases:
        for bout_id in selected_bout_ids:
            if bout_id not in common_bouts:
                original = block_index[(model_alias, bout_id, "original")]
                if original.complete:
                    exclusions.append(
                        Exclusion(
                            scope_id="common",
                            bout_id=bout_id,
                            model_alias=model_alias,
                            variant="original",
                            reason_code="outside_common_scope",
                            reason=(
                                "At least one other participating model has an "
                                "incomplete original block"
                            ),
                            actual_count=original.successful_count,
                            required_count=original.required_count,
                        )
                    )
                else:
                    exclusions.append(
                        _block_exclusion("common", original, "incomplete_original")
                    )
            if bout_id not in position_common_bouts:
                original = block_index[(model_alias, bout_id, "original")]
                swapped = block_index[(model_alias, bout_id, "swapped")]
                if original.complete and swapped.complete:
                    exclusions.append(
                        Exclusion(
                            scope_id="position:common",
                            bout_id=bout_id,
                            model_alias=model_alias,
                            reason_code="outside_position_common_scope",
                            reason=(
                                "At least one other participating model has an "
                                "incomplete original or swapped block"
                            ),
                            actual_count=(
                                original.successful_count + swapped.successful_count
                            ),
                            required_count=(
                                original.required_count + swapped.required_count
                            ),
                        )
                    )
                else:
                    deficient = swapped if original.complete else original
                    code = (
                        "incomplete_swapped"
                        if original.complete
                        else "incomplete_original"
                    )
                    exclusions.append(
                        _block_exclusion("position:common", deficient, code)
                    )

    probability_scopes: list[ProbabilityScope] = []
    for model_alias in model_aliases:
        for base_scope_id, bout_ids in (
            (
                f"model:{model_alias}",
                tuple(
                    bout_id
                    for bout_id in selected_bout_ids
                    if bout_id in complete_original[model_alias]
                ),
            ),
            ("common", common_bouts),
        ):
            eligible_cases: list[ProbabilityCase] = []
            scope_label = "common" if base_scope_id == "common" else "individual"
            probability_scope_id = f"probability:{scope_label}:{model_alias}"
            for bout_id in bout_ids:
                original = block_index[(model_alias, bout_id, "original")]
                for case in original.cases:
                    actual = sum(
                        vote.probability_player_1 is not None
                        for vote in case.model_votes
                    )
                    required = len(case.model_votes)
                    if actual == required:
                        eligible_cases.append(
                            ProbabilityCase(bout_id=bout_id, collegium=case.collegium)
                        )
                    else:
                        exclusions.append(
                            Exclusion(
                                scope_id=probability_scope_id,
                                bout_id=bout_id,
                                model_alias=model_alias,
                                variant="original",
                                collegium=case.collegium,
                                metric="probabilistic_metrics",
                                reason_code="incomplete_probabilities",
                                reason=(
                                    f"Only {actual} of {required} original votes contain "
                                    "provider probabilities"
                                ),
                                actual_count=actual,
                                required_count=required,
                            )
                        )
            probability_scopes.append(
                ProbabilityScope(
                    scope_id=probability_scope_id,
                    base_scope_id=base_scope_id,
                    model_alias=model_alias,
                    cases=tuple(eligible_cases),
                )
            )

    return PreparedAnalysis(
        selected_bout_ids=selected_bout_ids,
        model_aliases=model_aliases,
        human_votes=humans,
        blocks=tuple(blocks),
        model_scopes=tuple(model_scopes),
        common_scope=common_scope,
        position_scopes=tuple(position_scopes),
        position_common_scope=position_common_scope,
        probability_scopes=tuple(probability_scopes),
        exclusions=tuple(exclusions),
    )


def _block_exclusion(
    scope_id: str, block: PreparedBlock, reason_code: str
) -> Exclusion:
    label = "original" if block.variant == "original" else "swapped"
    return Exclusion(
        scope_id=scope_id,
        bout_id=block.bout_id,
        model_alias=block.model_alias,
        variant=block.variant,
        reason_code=reason_code,
        reason=(
            f"Only {block.successful_count} of {block.required_count} required "
            f"{label} votes succeeded ({block.planned_count} planned)"
        ),
        actual_count=block.successful_count,
        required_count=block.required_count,
    )


# Short alias for pipeline callers.
prepare_inputs = prepare_analysis_data


__all__ = [
    "HUMAN_COLLEGIUM_KEYS",
    "PreparedAnalysis",
    "PreparedBlock",
    "REQUIRED_VOTES_PER_BLOCK",
    "prepare_analysis_data",
    "prepare_inputs",
]

